import os
import random
import numpy as np
import torch


class Config:
    # --------------------------------------------------------------------------
    # Directories & Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    TRAIN_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DIR = os.path.join(INPUT_DIR, "test")

    # Metadata generated by the analysis script
    METADATA_DIR = "./metadata"
    METADATA_TRAIN = os.path.join(METADATA_DIR, "train.csv")
    METADATA_VAL = os.path.join(METADATA_DIR, "val.csv")
    METADATA_TEST = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching processed data
    WORKING_DIR = "./working/idea_optimized"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Submission output
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # --------------------------------------------------------------------------
    IMG_SIZE = 224
    NUM_CHANNELS = 12  # 4 modalities * 3 slices

    # Volumetric Stride (Cite Lesson 00110: Fixed Spatial Strides)
    STRIDE = 5

    # ROI Selection
    ROI_DEPTH_MIN = 0.15
    ROI_DEPTH_MAX = 0.85

    # Circuit Breaker
    CORRUPTION_THRESHOLD = 0.01  # Abort if >1% data corrupt

    # --------------------------------------------------------------------------
    # Model Hyperparameters
    # --------------------------------------------------------------------------
    MODEL_NAME = "efficientnet_b0"
    DROPOUT_RATE = 0.5
    NUM_CLASSES = 1
    STEM_GROUPS = 4  # Grouped convolutions for modality isolation

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 32
    NUM_EPOCHS = 30
    LEARNING_RATE = 1e-4  # Low LR
    WEIGHT_DECAY = 1e-2  # Aggressive Weight Decay
    PATIENCE = 5  # Early Stopping
    NUM_WORKERS = 4  # Data loading workers

    # Augmentation
    ROTATION_DEGREES = 15

    # Debugging / Development
    # Set to None to use full dataset, or an integer to limit samples
    DEBUG_SAMPLE_SIZE = None

    # --------------------------------------------------------------------------
    # Caching Paths
    # --------------------------------------------------------------------------
    # Using .npy for numpy array storage as requested (or parquet for metadata)
    CACHE_TRAIN_DATA = os.path.join(WORKING_DIR, "train_data.npy")
    CACHE_TRAIN_LABELS = os.path.join(WORKING_DIR, "train_labels.npy")
    CACHE_VAL_DATA = os.path.join(WORKING_DIR, "val_data.npy")
    CACHE_VAL_LABELS = os.path.join(WORKING_DIR, "val_labels.npy")
    CACHE_TEST_DATA = os.path.join(WORKING_DIR, "test_data.npy")
    CACHE_TEST_IDS = os.path.join(WORKING_DIR, "test_ids.npy")


def setup_reproducibility(seed=Config.SEED):
    """
    Sets random seeds for python, numpy, and torch to ensure reproducibility.
    """
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)

    # Ensure deterministic behavior in cuDNN
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

    os.environ["PYTHONHASHSEED"] = str(seed)
